import{_ as n,l as s,o as e,c as i,v as t,p as l,x as r,d,i as E,S as B}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"BCNF 与 3NF 取舍","description":"","frontmatter":{"title":"BCNF 与 3NF 取舍","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bcnf-3nf.md","filePath":"cs/bcnf-3nf.md","lastUpdated":1789023840000}'),F={name:"cs/bcnf-3nf.md"};function c(N,a,p,h,f,_){const o=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="bcnf-与-3nf-取舍" tabindex="-1">BCNF 与 3NF 取舍 <a class="header-anchor" href="#bcnf-与-3nf-取舍" aria-label="Permalink to &quot;BCNF 与 3NF 取舍&quot;">​</a></h1><div class="epigraph"><p>BCNF 要求每个决定因素都是候选键；3NF 允许对键的传递依赖以外的例外，以便有时保住依赖与无损。</p><footer>—— 据 Codd 对 3NF；Boyce–Codd；Date；Bernstein 合成算法对照</footer></div><p><a href="/cs/normal-forms">上一课</a>用函数依赖解释更新异常，并给出分解。本课不重定义 FD。缺口是两档范式的取舍：BCNF 更严，可能被迫拆掉「每个 FD 都能在某一张表里检查」；3NF 保证无损且保持依赖的合成存在，但允许少量冗余。视图下一课才把宽表变回来给用户看。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>范式课留下 3NF/BCNF 名字。BCNF：对关系 R 上成立的每个非平凡 X→Y，X 都是超键。反例：两个重叠候选键时，3NF 过、BCNF 不过。分解到 BCNF 总可无损，但不总保持依赖——应用必须连接后才能检查某条 FD。缺口是<strong>选哪一档作为设计目标</strong>。</p><p><span class="marginnote">保持依赖：每条 FD 在某一分解分量内可检查。3NF 合成算法对准这一目标。BCNF 追的是消除决定因素非键的冗余。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列出候选键与 FD 闭包。能 BCNF 且保持依赖则取 BCNF。否则在「冗余」与「检查 FD 要连接」之间显式选择，而不是让应用偷偷存宽表。本课不把 4NF 多值依赖插进主干必做。</p>',8)),(e(),l(B,null,{default:r(()=>[E(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FD%5B%22%E5%87%BD%E6%95%B0%E4%BE%9D%E8%B5%96%22%5D%20--%3E%20BCNF%5B%22%E5%86%B3%E5%AE%9A%E5%9B%A0%E7%B4%A0%E5%BF%85%E9%A1%BB%E6%98%AF%E9%94%AE%22%5D%0A%20%20FD%20--%3E%20TNF%5B%223NF%3A%20%E5%8F%AF%E5%AF%B9%E9%9D%9E%E9%94%AE%E7%95%99%E4%BE%8B%E5%A4%96%22%5D%0A%20%20BCNF%20--%3E%20TRADE%5B%22%E6%88%96%E6%8B%86%E6%8E%89%E4%BF%9D%E6%8C%81%E6%80%A7%22%5D%0A%20%20TNF%20--%3E%20KEEP%5B%22%E6%97%A0%E6%8D%9F%E4%B8%94%E5%B8%B8%E4%BF%9D%E6%8C%81%E4%BE%9D%E8%B5%96%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>取舍发生在模式层，查询仍用连接恢复。<a href="/cs/predicate-pushdown">谓词下推</a> 不能代替分解：异常是写出来的，不是读计划慢。后课物化视图用空间换连接，那是另一份合同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把「反规范化总是为了性能」写成默认建议；那要有代价数字与异常预算。用户还想看宽表时，下一课视图。</p><p>后课默认：设计时在 BCNF 与 3NF 间有意识选择。给用户的宽接口可以是视图。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BCNF 更严；3NF 更易保持依赖。</li><li>分解无损与保持依赖不可总同时在 BCNF 拿到。</li><li>视图与物化下一课。</li><li>出处：Codd；Boyce–Codd；Date。</li></ul>',7))])}const m=n(F,[["render",c]]);export{D as __pageData,m as default};
